  signature_registry_set: { status: 'supported', ownershipClass: 'mainSharedMutating', allowedPhases: 'all', destructiveRisk: 'metadata-write', reason: 'Mutates the audit-only finding signatureTag registry (propose/approve/alias/deprecate) in file-backed .lattice/learning/ storage. No gate reads it; it cannot satisfy Proofbound DONE gate evidence, retired remote-completion fields or release readiness. Cross-session serialized by shared file write; not a per-story owner lease.' },
