  learning_validate: { memoryRetrieval: true, status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only Experience Layer referential re-validation: derives finding-signals through the store read ports (no persist), checks each signal\'s anchor files against the current git HEAD, and reports valid-rate / drift-rate. Writes nothing, creates no derived index/cache, files no findings, and never touches a gate. Cannot satisfy DONE gate evidence, retired remote-completion fields or release readiness.' },
