  review_escalation_status: { status: 'supported', ownershipClass: 'readOnly', allowedPhases: 'all', destructiveRisk: 'none', reason: 'Read-only DONE review escalation diagnostic. Reports whether first-round verified reviewer findings or explicitlyConfiguredHighRiskPolicyRequires3x2 trigger 3x2 host quorum, or a degraded 3x1 fallback, without mutating lifecycle artifacts or claiming retired remote-completion fields or release readiness.' },
  review_escalation_policy_set: { status: 'gateEvidence', gateEvidence: true, ownershipClass: 'storyScopedMutating', allowedPhases: ['DEV', 'REVIEW', 'TEST', 'DONE'], destructiveRisk: 'metadata-write', reason: 'Records a structured explicit high-risk policy fact for explicitlyConfiguredHighRiskPolicyRequires3x2, bound to policyVersion, story/risk or milestone, sourcePolicyRef, rolloutStage, issuer, current head/material hash, and degraded fallback eligibility. It can satisfy only the local review escalation DONE gate trigger and must never claim retired remote-completion fields or release readiness.' },
